 '<b>📝 My private journal</b><textarea id="ldJ" style="width:100%;height:110px;font:15px Georgia;border:1px solid #e8b8a8;border-radius:10px;padding:8px;box-sizing:border-box;margin-top:4px" placeholder="What happened? How did it feel?">'+esc(S.j[i]||'')+'</textarea><div style="font-size:12px;opacity:.7">Saved on this device only.</div>'+
 '<p><label style="font-size:18px"><input type="checkbox" id="ldDone"'+(done?' checked':'')+' style="width:20px;height:20px"> I did today\'s dare</label></p>'+
 '<button id="ldPrev" style="'+bs()+'">⬅ Previous</button> <button id="ldClose" style="'+bs(1)+'">Done</button> <button id="ldNext" style="'+bs()+'">Next ➡</button>';
 P.style.display='block';
 P.querySelector('#ldV').onchange=e=>{S.v=e.target.value;save();P.querySelector('#ldVT').innerHTML=vtext(i)};
 P.querySelector('#ldJ').oninput=e=>{S.j[i]=e.target.value;save()};
 P.querySelector('#ldDone').onchange=e=>{S.done=S.done.filter(z=>z!=i);if(e.target.checked)S.done.push(i);save()};
