 T('Certificate of Love',450,130,46,'#a0405a','center');T('This certifies that',450,180,18,INK,'center','italic ');T(S.name||'(tap “Add names”)',450,232,34,GOLD,'center');
 T('completed all 40 days of love, kindness and faithfulness.',450,280,18,INK,'center','');T('“Love never fails.” 1 Corinthians 13:8',450,320,17,ROSE,'center','italic ');
